.mac-select {
  position: relative;
}
.mac-select select {
  -webkit-appearance: none !important;
  -moz-appearance: none !important;
  appearance: none !important;
  border: none;
  background: #fff;
}
.mac-select:after {
  content: "";
  z-index: 3;
  top: 54%;
  right: 8px;
  border: solid transparent;
  height: 0;
  width: 0;
  position: absolute;
  pointer-events: none;
  border-color: rgba(0, 0, 0, 0);
  border-top-color: #000000;
  border-width: 5px;
  margin-left: -10px;
  transform: translateY(-50%);
}

.main-theadbox {
  display: grid;
  grid-auto-columns: 1fr;
  grid-template-columns: 1fr 1fr 1fr 1fr 1fr 1fr 1fr 1fr 1fr 1fr;
  grid-template-rows: 1fr;
  gap: 0px 0px;
  grid-template-areas: "t1 t2 t3 t4 t5 t6 t7 t8 t9 t10";
}

.t1 {
  grid-area: t1;
}

.t2 {
  grid-area: t2;
}

.t3 {
  grid-area: t3;
}

.t4 {
  grid-area: t4;
}

.t5 {
  grid-area: t5;
}

.t6 {
  grid-area: t6;
}

.t7 {
  grid-area: t7;
}

.t8 {
  grid-area: t8;
}

.t9 {
  grid-area: t9;
}
.t10 {
  grid-area: t10;
}

.main-theadbox > div {
  padding: 0px;
  display: grid;
  place-items: center;
  border: 1px solid #ccc;
}
.main-theadboxes {
  display: grid;
  grid-auto-columns: 1fr;
  grid-template-columns: 1fr 1fr 1fr 1fr 1fr 1fr 1fr 1fr 1fr 1fr;
  grid-template-rows: 1fr;
  gap: 0px 0px;
  grid-template-areas: "t1 t2 t3 t4 t5 t6 t7 t8 t9 t10";
}
.main-theadboxes > div {
