.optionss input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.checkmarks {
  position: absolute;
  top: 25%;
  right: 20px;
  height: 25px;
  width: 25px;
  background-color: #eee;
}

.optionss input:checked ~ .checkmarks {
  background-color: #2196f3;
}

.checkmarks:after {
  content: "";
  position: absolute;
  display: none;
}

.optionss input:checked ~ .checkmarks:after {
  display: block;
}

.optionss .checkmarks:after {
  left: 9px;
  top: 5px;
  width: 5px;
  height: 10px;
  border: solid white;
  border-width: 0 3px 3px 0;
  -webkit-transform: rotate(45deg);
  -ms-transform: rotate(45deg);
  transform: rotate(45deg);
}

