:root {
  --primary: #c62026;
  --secondary: #293867;
  --white: #fff;
  --black: #111;
}
@import url("https://fonts.googleapis.com/css2?family=Roboto:wght@100;300;400;500;700;900&display=swap");
body {
  margin: 0;
  padding: 0;
  overflow-x: hidden;
  font-family: "Roboto", sans-serif;
}
header {
  display: block;
  box-shadow: 2px 2px 2px rgba(0, 0, 0, 0.3);
}
.main-red-block {
  position: fixed;
  top: 0;
  left: 0;
