  padding: 15px 0;
}
.logo-block a {
  width: 120px;
}
.user-login-btn .reg-btn {
  color: var(--white);
  padding: 6px 22px;
  display: inline-block;
  font-size: 16px;
  line-height: 20px;
  font-weight: 500;
}
.user-login-btn div:first-child .reg-btn {
  background: transparent;
}
.user-login-btn div:last-child .reg-btn {
  background: var(--primary);
}
.user-login-btn div a:hover {
  background: var(--secondary);
}
.drop-menu-block {
  background: rgba(0, 0, 0, 0.5);
  padding: 0;
  list-style: none;
  position: absolute;
  right: 0;
  min-width: 120px;
  display: none;
  flex-direction: column;
}
.drop-menu-block li a {
  padding: 4px 10px;
  display: block;
}
.drop-menu-block li:first-child a {
  background: var(--secondary);
  color: var(--white);
}
.drop-menu-block li:last-child a {
  background: var(--white);
  color: var(--secondary);
}

.user-login-btn .drop-block:hover .drop-menu-block {
  display: flex;
}
.main-slider,
.main-slider .carousel,
.main-slider .carousel div {
  height: 100vh;
  width: 100%;
}
.main-slider div img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.main-slider .carousel .carousel-item:after {
  position: absolute;
  content: "";
  background: rgba(0, 0, 0, 0.5);
  inset: 0;
  z-index: 4;
}
.dicover-block {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 33;
  left: 0%;
  padding: 0 5%;
  max-width: 650px;
  width: 100%;
}
.dicover-block h1 {
