.circle-small {
  display: inline-block;
  position: relative;
  width: 30px;
  height: 30px;
  margin: 0px;
  text-align: center;
}
.circle-small .fa-check-circle {
  color: var(--primary);
  font-size: 16px;
}
.circle-small svg {
  width: 80px;
  height: 80px;
  transform: scale(0.3);
  margin: -25px 0 0 -25px;
}

.circle-small .bg {
  fill: none;
  stroke-width: 6px;
  stroke: #ccc;
}

.circle-small .progress {
  fill: none;
  stroke-width: 6px;
  stroke: var(--primary);
  stroke-linecap: round;
  stroke-dasharray: 232.36;
  transform: rotate(-90deg);
  transform-origin: 50% 50%;
}

.circle-small .progress.one {
  stroke-dashoffset: 80;
  /* animation: one 2.5s ease-in-out, appear 1s; */
}

.circle-small .progress.two {
  stroke-dashoffset: 233;
  /* animation: two 3.5s ease-in-out, appear 2s; */
}

.circle-small .text {
  position: absolute;
  width: 100%;
  top: 26px;
  font-size: 17px;
  text-align: center;
  font-weight: 400;
  line-height: 16px;
}
.pyramid-img {
