}
.pie .pie-text-1 {
  position: absolute;
  top: 39%;
  right: 50%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 10px;
  transform: translateX(50%);
}
.pie .pie-text-1 i {
  font-size: 78px;
