}
.pie .percentage {
  position: absolute;
  top: 0;
  right: 16%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}
.pie .refresh {
  position: absolute;
  bottom: 5%;
  left: 50%;
  transform: translateX(-50%);
}
.pie .refresh i {
  font-size: 30px;
  cursor: pointer;
}
.slick-track{
  display: flex !important;
  justify-content: center;
  align-items: center;
}
@keyframes big {
  from {
    stroke-dashoffset: 326.56;
  }
  to {
    stroke-dashoffset: 60;
  }
}

@keyframes one {
  from {
    stroke-dashoffset: 232.36;
  }
  to {
    stroke-dashoffset: 80;
  }
}

@keyframes two {
  from {
    stroke-dashoffset: 232.36;
  }
  to {
    stroke-dashoffset: 140;
  }
}

@keyframes appear {
  0%,
  50% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
