.main_banner {
  background-image: url(../images/banner_bg.png);
  background-position: center;
  background-repeat: no-repeat;
  background-size: cover;
  height: 100vh;
  position: relative;
  &::after {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(
      180deg,
      rgba(3, 112, 241, 0.82) 0%,
      rgba(255, 255, 255, 0.82) 100%
    );
  }
  .banner_text {
    border: 5px solid #fff;
    position: relative;
    z-index: 98;
    padding: 100px 150px;
    @include lg {
      padding: 30px;
      margin: 0;
    }
    position: relative;
    overflow: hidden;
    &::after {
      content: "";
      position: absolute;
      top: -14px;
      right: -2px;
      width: 21%;
      height: 100px;
      background-image: url(../images/banner_lw.svg);
      background-position: center;
      background-repeat: no-repeat;
      background-size: contain;
      @include sm {
        display: none;
      }
    }
    &::before {
      content: "";
      position: absolute;
      bottom: -5px;
      left: -4px;
      width: 216px;
      height: 100px;
      background-image: url(../images/banner_rw.svg);
      background-position: center;
      background-repeat: no-repeat;
      background-size: contain;
      @include sm {
        display: none;
      }
    }
    h1 {
      text-align: center;
      font-size: 48px;
      font-weight: 700;
      line-height: 52px;
      color: #fff;
      font-family: $font;
      @include sm {
        font-size: 35px;
      }
    }
  }
}

