.chosse_banner {
  overflow: hidden;
  background-image: url(../images/chosse-b.JPG);
  background-position: center;
  background-repeat: no-repeat;
  background-size: cover;
  height: 200px;
  position: relative;
  &::before {
    content: "";
    display: block;
    position: absolute;
    top: 0;
    background-color: rgb(44 135 240 / 49%);
    width: 100%;
    height: 100%;
  }
  h3 {
    color: #fff;
    font-size: 35px;
    font-weight: 700;
  }
  .clip_left {
    clip-path: polygon(80% 40%, 0 75%, 15% 100%);
    background-color: #fff;
    height: 100%;
    width: 227px;
    position: absolute;
    top: 9px;
    left: -43px;
  }
  .clip_right {
    clip-path: polygon(80% 40%, 0 75%, 15% 100%);
    background-color: #fff;
    height: 100%;
    width: 227px;
    position: absolute;
    top: -4%;
    right: -37px;
    transform: rotate(180deg);
  }
}

