    font-size: 40px;
    font-weight: 500;
    color: #000;
  }
  .slider_testimonal {
    background-color: #3699fa;
    padding: 25px 50px;
    @include md {
      padding: 10px;
    }
    .testimonal_box {
      background-color: white;
      padding: 50px 20px;
      @include md {
        padding: 30px;
      }
      border-radius: 20px;
      .profile_user {
        width: 60px;
        height: 60px;
        border-radius: 50px;
        flex-shrink: 0;
        overflow: hidden;
      }
      h5 {
        font-size: 17px;
        font-weight: 400;
        color: #000;
      }
      p {
        font-size: 17px;
        font-weight: 400;
        color: #000;
        span {
          font-size: 14px;
          font-weight: 500;
          color: #000000d2;
        }
      }
      .star {
        svg {
          fill: #f5b144;
          font-size: 14px;
        }
      }
    }
    .slick-track {
      display: flex;
      align-items: center;
      gap: 20px;
    }
  }
}
